import{_ as t,o,c as i,a3 as a}from"./chunks/framework.DhF4LrUq.js";const u=JSON.parse('{"title":"Inbound webhooks","description":"Inbound webhooks - the five authenticated receivers (GitHub, Jenkins, GitLab, App Store, Google Play), their setup, and their signature contracts.","frontmatter":{"description":"Inbound webhooks - the five authenticated receivers (GitHub, Jenkins, GitLab, App Store, Google Play), their setup, and their signature contracts."},"headers":[],"relativePath":"how-to/automation/webhooks.md","filePath":"how-to/automation/webhooks.md"}'),s={name:"how-to/automation/webhooks.md"};function r(n,e,d,h,l,p){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="inbound-webhooks" tabindex="-1">Inbound webhooks <a class="header-anchor" href="#inbound-webhooks" aria-label="Permalink to &quot;Inbound webhooks&quot;">​</a></h1><p>ShipperDog receives events from five providers through authenticated inbound receivers. Each delivery&#39;s own provider authentication <em>is</em> the request&#39;s authentication — there is no user token on these routes. Your <strong>platform operator</strong> switches each receiver on; this page is the setup and signature contract per provider.</p><table tabindex="0"><thead><tr><th>Receiver</th><th>Provider</th><th>Authentication</th><th>On/off switch</th></tr></thead><tbody><tr><td><code>POST /webhooks/github</code></td><td>GitHub Actions</td><td>HMAC-SHA256 over the body (<code>X-Hub-Signature-256</code>)</td><td><code>WEBHOOKS_GITHUB_SECRETS</code> (empty = off)</td></tr><tr><td><code>POST /webhooks/jenkins</code></td><td>Jenkins</td><td>The receiver-defined contract: HMAC-SHA256 (<code>X-Shipperdog-Signature</code>) computed by your pipeline</td><td><code>WEBHOOKS_JENKINS_SECRETS</code></td></tr><tr><td><code>POST /webhooks/gitlab</code></td><td>GitLab</td><td><code>X-Gitlab-Token</code> compared constant-time (GitLab signs nothing — the transport must be TLS)</td><td><code>WEBHOOKS_GITLAB_SECRETS</code></td></tr><tr><td><code>POST /webhooks/appstore</code></td><td>App Store</td><td>Apple&#39;s JWS <code>signedPayload</code> (ES256, certificate chain to Apple&#39;s root) plus a bundle-id allowlist</td><td><code>WEBHOOKS_APPSTORE_BUNDLE_IDS</code></td></tr><tr><td><code>POST /webhooks/google-play</code></td><td>Google Play RTDN</td><td>Pub/Sub push OIDC bearer (RS256 against Google&#39;s public keys; issuer, audience, expiry, freshness)</td><td><code>WEBHOOKS_GOOGLE_PLAY_AUDIENCE</code></td></tr></tbody></table><h2 id="set-up-the-github-receiver" tabindex="-1">Set up the GitHub receiver <a class="header-anchor" href="#set-up-the-github-receiver" aria-label="Permalink to &quot;Set up the GitHub receiver&quot;">​</a></h2><ol><li><p>Your platform operator sets <code>WEBHOOKS_GITHUB_SECRETS</code> to the HMAC secret(s) — a <em>list</em>, so rotation is overlap: add the new secret, remove the old once deliveries flow.</p></li><li><p>In your GitHub repository: <strong>Settings — Webhooks — Add webhook</strong>. URL <code>https://&lt;your-deployment&gt;/webhooks/github</code>, content type <code>application/json</code>, the same secret.</p></li><li><p>Subscribe to the <strong>workflow run</strong> event. Completed runs whose commit matches artifacts&#39; frozen <code>git_commit</code> claims backfill their run URL and pipeline name (backfill-only — values an upload already asserted are never overwritten). Teams using the <a href="/shipperdog/snapshot/how-to/automation/github-actions">upload action</a> get a no-op; teams uploading other ways still get run URLs attached.</p></li></ol><h2 id="set-up-the-jenkins-receiver" tabindex="-1">Set up the Jenkins receiver <a class="header-anchor" href="#set-up-the-jenkins-receiver" aria-label="Permalink to &quot;Set up the Jenkins receiver&quot;">​</a></h2><p>Jenkins has no standard webhook signature, so the receiver defines a thin contract your pipeline computes (the <code>openssl</code> one-liner ships in the <a href="/shipperdog/snapshot/how-to/automation/jenkins">Jenkins template</a>): the exact body bytes signed <code>X-Shipperdog-Signature: sha256=hex(HMAC-SHA256(secret, body))</code>, with a build-completed JSON body. Your operator enables it with <code>WEBHOOKS_JENKINS_SECRETS</code>.</p><h2 id="set-up-the-gitlab-receiver" tabindex="-1">Set up the GitLab receiver <a class="header-anchor" href="#set-up-the-gitlab-receiver" aria-label="Permalink to &quot;Set up the GitLab receiver&quot;">​</a></h2><ol><li>Your operator sets <code>WEBHOOKS_GITLAB_SECRETS</code>.</li><li>In GitLab: <strong>Settings — Webhooks</strong>, URL <code>https://&lt;your-deployment&gt;/webhooks/gitlab</code>, <code>application/json</code>, the same token, subscribed to the <strong>Pipeline</strong> event.</li></ol><p>A successful pipeline whose commit matches artifacts backfills their run URL and pipeline name, backfill-only. Because GitLab sends the token verbatim, TLS is not optional.</p><h2 id="set-up-the-app-store-receiver" tabindex="-1">Set up the App Store receiver <a class="header-anchor" href="#set-up-the-app-store-receiver" aria-label="Permalink to &quot;Set up the App Store receiver&quot;">​</a></h2><ol><li><p>Your operator sets <code>WEBHOOKS_APPSTORE_BUNDLE_IDS</code> to the bundle ids allowed through (empty effectively off: everything ignores).</p></li><li><p>In App Store Connect: <strong>App information — App Store Server Notifications</strong>, point the production (and sandbox) endpoint at <code>https://&lt;your-deployment&gt;/webhooks/appstore</code>.</p></li></ol><p>Apple signs every notification (<code>signedPayload</code>, ES256 with a certificate chain the receiver validates to Apple&#39;s root CA), and the bundle-id allowlist authorizes — authenticity, then authorization. Store events (a TestFlight build&#39;s processing state, phased-release day ticks) map onto the release dashboard&#39;s channel facts.</p><h2 id="set-up-the-google-play-receiver" tabindex="-1">Set up the Google Play receiver <a class="header-anchor" href="#set-up-the-google-play-receiver" aria-label="Permalink to &quot;Set up the Google Play receiver&quot;">​</a></h2><ol><li><p>Your operator sets <code>WEBHOOKS_GOOGLE_PLAY_AUDIENCE</code> — the audience string Google&#39;s push carries for your deployment.</p></li><li><p>In Google Play: <strong>Monetization setup — Real-time developer notifications</strong>, the Pub/Sub topic&#39;s push endpoint pointing at <code>https://&lt;your-deployment&gt;/webhooks/google-play</code>.</p></li></ol><p>Google&#39;s Pub/Sub push signs each delivery as an OIDC bearer token (RS256 against Google&#39;s public keys); the receiver verifies issuer, audience, expiry, and freshness, with an optional sender-email allowlist your operator may set.</p><h2 id="what-every-receiver-answers" tabindex="-1">What every receiver answers <a class="header-anchor" href="#what-every-receiver-answers" aria-label="Permalink to &quot;What every receiver answers&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ACCEPTED&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;deliveryId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;72d3162e-…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><strong><code>ACCEPTED</code></strong> — consumed and acted on.</li><li><strong><code>IGNORED</code></strong> — consumed, deliberately not acted on (an unknown event, a foreign bundle, a non-success build): providers expect 2xx-or-retry, and a no-op must not churn retries.</li><li><strong><code>DUPLICATE</code></strong> — the delivery-id ledger already processed this delivery: the idempotent no-op.</li></ul><p>Rejections are uniform by family — never a hint which leg refused:</p><ul><li>Shared-secret family (GitHub, Jenkins, GitLab): every authenticity failure answers <strong>401 <code>WEBHOOK_SIGNATURE_REJECTED</code></strong>.</li><li>Store family (App Store, Google Play): every authenticity failure answers <strong>400 <code>WEBHOOK_DELIVERY_REJECTED</code></strong>.</li><li>A verified sender&#39;s unreadable body answers <strong>400 <code>WEBHOOK_PAYLOAD_MALFORMED</code></strong>; a body beyond the ceiling <strong>413 <code>WEBHOOK_PAYLOAD_TOO_LARGE</code></strong>.</li></ul><p>Two replay defenses apply everywhere: a timestamp window (providers that stamp deliveries) and the delivery-id ledger (every provider). Every outcome is audited — never the secret, never the raw payload.</p><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/automation/github-actions">GitHub Actions</a> · <a href="/shipperdog/snapshot/how-to/automation/jenkins">Jenkins</a> · <a href="/shipperdog/snapshot/how-to/automation/gitlab">GitLab</a></p>',23)])])}const b=t(s,[["render",r]]);export{u as __pageData,b as default};
